import { connection } from 'next/server'

export default async function Home() {
  await connection()
  const now = new Date()

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>The current server time is:</p>
      <time dateTime={now.toISOString()}>{now.toLocaleString()}</time>
    </main>
  )
}

